/* Mandatory reset & hidden attribute rule */
[hidden] {
  display: none !important;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  /* Cohesive retro pixel palette (4 key colors + shades) */
  --color-bg: #2b2353;
  --color-board: #1f3d2e;
  --color-wood: #c07a3e;
  --color-wood-dark: #824419;
  --color-desk-empty: #e2ab70;
  --color-occupied: #4a9fd5;
  --color-occupied-dark: #27658d;
  --color-cream: #f4ecd8;
  --color-chalk: #fefefe;
  --color-shadow: #141026;
  --color-alert: #e05b5b;
}

body {
  font-family: "Courier New", Courier, monospace, monospace;
  font-size: 16px;
  background-color: var(--color-bg);
  color: var(--color-cream);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  /* Subtle pixel checkerboard backdrop */
  background-image:
    linear-gradient(45deg, #221c44 25%, transparent 25%),
    linear-gradient(-45deg, #221c44 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #221c44 75%),
    linear-gradient(-45deg, transparent 75%, #221c44 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0px;
}

.classroom-card {
  background-color: #3b306b;
  width: 100%;
  max-width: 680px;
  border: 4px solid var(--color-shadow);
  box-shadow: 8px 8px 0px var(--color-shadow);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

/* Blackboard Title Banner */
.blackboard {
  background-color: var(--color-board);
  border: 4px solid var(--color-wood);
  box-shadow: inset 0 0 0 2px var(--color-wood-dark), 4px 4px 0 var(--color-shadow);
  text-align: center;
  padding: 12px 8px;
}

.classroom-title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  color: var(--color-chalk);
  text-shadow: 2px 2px 0 var(--color-shadow);
}

.blackboard-sub {
  font-size: 0.95rem;
  color: #bfdbcd;
  margin-top: 4px;
  letter-spacing: 1px;
}

/* Dashboard Panel */
.dashboard-panel {
  background-color: #2e2655;
  border: 3px solid var(--color-shadow);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.status-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.status-label {
  font-weight: bold;
  font-size: 1rem;
  letter-spacing: 1px;
  color: #f7d070;
}

.counter-badge {
  background: var(--color-board);
  border: 2px solid var(--color-chalk);
  padding: 6px 12px;
  font-weight: bold;
  font-size: 1.1rem;
  color: var(--color-chalk);
  box-shadow: 2px 2px 0 var(--color-shadow);
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.input-label {
  font-weight: bold;
  font-size: 0.95rem;
}

.pixel-input {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 12px;
  background-color: var(--color-cream);
  color: var(--color-shadow);
  border: 3px solid var(--color-shadow);
  box-shadow: inset 2px 2px 0 rgba(0, 0, 0, 0.25);
  outline: none;
  width: 100%;
}

.pixel-input:focus {
  outline: 3px solid #f7d070;
  outline-offset: 1px;
  background-color: #fffdf8;
}

.feedback-msg {
  font-size: 0.85rem;
  min-height: 1.1rem;
  color: #ffd685;
}

.feedback-msg.alert {
  color: var(--color-alert);
  font-weight: bold;
}

/* Room Floor & Podium */
.room-floor {
  background: #32295e;
  border: 3px solid var(--color-shadow);
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.teacher-desk {
  background: var(--color-wood);
  border: 3px solid var(--color-wood-dark);
  box-shadow: 0 4px 0 var(--color-shadow);
  color: var(--color-cream);
  text-align: center;
  padding: 6px;
  width: 60%;
  max-width: 240px;
  margin: 0 auto;
}

.teacher-label {
  font-size: 0.8rem;
  font-weight: bold;
  letter-spacing: 1px;
  display: block;
}

/* 3 Rows x 4 Columns Desk Grid */
.grid-container {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

@media (max-width: 520px) {
  .grid-container {
    gap: 6px;
  }
}

/* Desk Button Card */
.desk-btn {
  font-family: inherit;
  cursor: pointer;
  border-radius: 0;
  border: 3px solid var(--color-shadow);
  box-shadow: 3px 3px 0 var(--color-shadow);
  padding: 10px 4px;
  min-height: 86px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  text-align: center;
  position: relative;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
  outline: none;
}

.desk-btn:focus-visible {
  outline: 3px solid #ffea79;
  outline-offset: 2px;
  z-index: 2;
}

.desk-btn:hover {
  filter: brightness(1.08);
}

.desk-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 var(--color-shadow);
}

/* Empty Desk Theme */
.desk-btn.vacant {
  background-color: var(--color-desk-empty);
  color: var(--color-wood-dark);
}

.desk-btn.vacant .desk-glyph {
  font-size: 1.2rem;
  line-height: 1;
}

.desk-btn.vacant .desk-pos {
  font-size: 0.75rem;
  font-weight: bold;
  text-transform: uppercase;
}

.desk-btn.vacant .desk-status-tag {
  font-size: 0.75rem;
  border: 1px dashed var(--color-wood-dark);
  padding: 2px 4px;
  background: rgba(255, 255, 255, 0.25);
}

/* Occupied Desk Theme */
.desk-btn.occupied {
  background-color: var(--color-occupied);
  color: var(--color-chalk);
  border-color: var(--color-shadow);
}

.desk-btn.occupied .desk-glyph {
  font-size: 1.2rem;
  line-height: 1;
}

.desk-btn.occupied .desk-name {
  font-weight: bold;
  font-size: 0.85rem;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 2px 2px;
  background-color: var(--color-occupied-dark);
  width: 95%;
}

.desk-btn.occupied .desk-action {
  font-size: 0.7rem;
  color: #ffd685;
  text-decoration: underline;
}

/* Footer Info */
.instructions {
  text-align: center;
  font-size: 0.85rem;
  color: #b8abd9;
  line-height: 1.4;
}

document.addEventListener('DOMContentLoaded', () => {
  const TOTAL_DESKS = 12;
  const ROWS = 3;
  const COLS = 4;

  // State: Array of 12 elements storing either student name string or null
  const desks = Array.from({ length: TOTAL_DESKS }, () => null);

  // DOM references
  const deskGrid = document.getElementById('deskGrid');
  const seatCounter = document.getElementById('seatCounter');
  const studentNameInput = document.getElementById('studentNameInput');
  const inputFeedback = document.getElementById('inputFeedback');

  /**
   * Returns the count of currently occupied seats.
   */
  function getOccupiedCount() {
    return desks.filter(student => student !== null).length;
  }

  /**
   * Updates the counter element and accessibility attributes.
   */
  function updateCounter() {
    const filled = getOccupiedCount();
    seatCounter.textContent = `${filled} / ${TOTAL_DESKS} seats filled`;
  }

  /**
   * Helper to set feedback messages.
   */
  function setFeedback(message, isAlert = false) {
    inputFeedback.textContent = message;
    if (isAlert) {
      inputFeedback.classList.add('alert');
    } else {
      inputFeedback.classList.remove('alert');
    }
  }

  /**
   * Render a single desk button element based on current state.
   */
  function renderDesk(index) {
    const student = desks[index];
    const deskBtn = deskGrid.children[index];
    if (!deskBtn) return;

    const row = Math.floor(index / COLS) + 1;
    const col = (index % COLS) + 1;
    const deskLabel = `R${row}C${col}`;

    if (student === null) {
      deskBtn.className = 'desk-btn vacant';
      deskBtn.setAttribute('aria-label', `Desk row ${row}, column ${col}, Empty. Click to seat student.`);
      deskBtn.innerHTML = `
        <span class="desk-pos">${deskLabel}</span>
        <span class="desk-glyph" aria-hidden="true">&#9633;</span>
        <span class="desk-status-tag">EMPTY</span>
      `;
    } else {
      deskBtn.className = 'desk-btn occupied';
      deskBtn.setAttribute('aria-label', `Desk row ${row}, column ${col}, occupied by ${student}. Click to clear desk.`);
      deskBtn.innerHTML = `
        <span class="desk-glyph" aria-hidden="true">&#9632;</span>
        <span class="desk-name" title="${student}">${student}</span>
        <span class="desk-action">CLEAR</span>
      `;
    }
  }

  /**
   * Handles clicking or pressing Enter/Space on any desk.
   */
  function handleDeskClick(index) {
    const currentOccupant = desks[index];
    const row = Math.floor(index / COLS) + 1;
    const col = (index % COLS) + 1;

    if (currentOccupant !== null) {
      // Clicking an occupied desk clears it
      desks[index] = null;
      renderDesk(index);
      updateCounter();
      setFeedback(`Cleared ${currentOccupant} from Desk R${row}C${col}.`);
    } else {
      // Clicking an empty desk seats the student from input
      const name = studentNameInput.value.trim();
      if (!name) {
        setFeedback('Please type a student name first to seat them!', true);
        studentNameInput.focus();
        return;
      }

      desks[index] = name;
      renderDesk(index);
      updateCounter();
      setFeedback(`Seated ${name} at Desk R${row}C${col}.`);
      studentNameInput.value = '';
      studentNameInput.focus();
    }
  }

  /**
   * Initialize the grid container with desk buttons and event listeners.
   */
  function initGrid() {
    deskGrid.innerHTML = '';
    for (let i = 0; i < TOTAL_DESKS; i++) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'desk-btn vacant';
      btn.dataset.index = i;
      btn.addEventListener('click', () => handleDeskClick(i));
      deskGrid.appendChild(btn);
      renderDesk(i);
    }
    updateCounter();
    setFeedback('Type a name and choose an empty desk.');
  }

  initGrid();
});
